def sha(data): return hashlib.sha256(data).hexdigest()
def once(s,o,n):
    if s.count(o)!=1: raise AssertionError('Unexpected source preimage: '+repr(o[:120]))
    return s.replace(o,n,1)

def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args()
    shell=a.root/'shell-kodi';a.out.mkdir(parents=True,exist_ok=True)
    activity=shell/ACTIVITY;pro=shell/PROUI
    assert sha(activity.read_bytes())==PARENT_ACTIVITY_SHA,'Not exact locked 2103271 Activity'
    assert sha(pro.read_bytes())==PARENT_PROUI_SHA,'Not exact locked 2103271 CobraProUi'
    patch=zlib.decompress(base64.b64decode(PATCH_B64)).decode()
    subprocess.run(['patch','-p1','--batch','--forward'],cwd=shell,input=patch,text=True,check=True)
    assert sha(activity.read_bytes())==AFTER_ACTIVITY_SHA,'Unexpected Activity patch result'
    assert sha(pro.read_bytes())==AFTER_PROUI_SHA,'Unexpected CobraProUi patch result'
    gradle=shell/GRADLE;g=gradle.read_text();g=once(g,'versionCode 2103271','versionCode 2103273');g=once(g,'versionName "1.0.9-Sports-Data-RC1"','versionName "1.0.9-Pro-Sports-Soccer-RC1"');gradle.write_text(g)
    script=a.root/'scripts/infinity_background_resume.py';v=script.read_text();v=once(v,'VERSION_CODE = 2103271','VERSION_CODE = 2103273');v=once(v,"RELEASE = '1.0.9-Sports-Data-RC1'",f"RELEASE = '{RELEASE}'");v=once(v,"BASE_COMMIT = 'fe36eda6020934e538b32f754d3175040960b2cc'",f"BASE_COMMIT = '{PARENT_COMMIT}'");v=once(v,"BASE_APK_SHA256 = '54223cd2dcc6ebbf1b0ddddc88114ca9c95541084077a7ea03dba7c6f7ac2259'",f"BASE_APK_SHA256 = '{PARENT_APK}'");script.write_text(v)
    package=a.root/'scripts/package_background_resume.py';v=package.read_text();v=v.replace('Infinity-2103271-Sports-Data-RC1','Infinity-2103273-Pro-Sports-Soccer-RC1');v=once(v,"'base_run':36755538846",f"'base_run':{PARENT_RUN}");v=once(v,"ROOT/'repairs/sports-data-2103271/DEVICE-TEST.md'","ROOT/'repairs/pro-sports-soccer-2103273/DEVICE-TEST.md'");package.write_text(v)
    receipt=a.root/'engine/background-resume-source.json';r=json.loads(receipt.read_text());r.update(base_source_commit=PARENT_COMMIT,base_apk_sha256=PARENT_APK,version_code=VERSION_CODE,release=RELEASE,candidate_locked=False,physical_device_verified=False,complete_product_audit=False,pro_sports_tab=True,pro_six_tabs=True,pro_live_sports_hero_source=True,pro_sports_live_now=True,pro_sports_my_teams=True,pro_sports_upcoming=True,pro_sports_leagues=True,pro_sports_watch_live=True,pro_sports_stats=True,pro_sports_multiview=True,soccer_enabled_by_default=True,soccer_premier_league=True,soccer_champions_league=True,soccer_mls=True,soccer_extended_leagues=True,sports_repository_preserved=True,sports_channel_resolver_preserved=True,manual_multiview_preserved=True)
    for n in [ACTIVITY,PROUI,GRADLE]:r['files'].setdefault(n,{})['after']=sha((shell/n).read_bytes())
    receipt.write_text(json.dumps(r,indent=2,sort_keys=True)+'\n')
    (a.out/'pro-sports-soccer.patch').write_text(patch)
    print('Applied 2103273 Pro Sports + Soccer over exact locked 2103271; existing Sports repository/player/provider/Multi-View owners preserved.')
if __name__=='__main__':main()
